import{_ as n,o as s,c as e,aO as l}from"./chunks/framework.vjUPZZJn.js";const u=JSON.parse('{"title":"PlantUML 中文字体设置：skinparam 与 style 两种写法","description":"","frontmatter":{"date":"2026-11-11T20:20:00.000Z","title":"PlantUML 中文字体设置：skinparam 与 style 两种写法","source":[["1-知识/工具/plantuml 设置中文字体"]],"tags":["工具","教程手册","PlantUML"],"categories":["工具"],"permalink":"/pages/cb303f"},"headers":[],"relativePath":"工具/PlantUML 中文字体设置：skinparam 与 style 两种写法.md","filePath":"工具/PlantUML 中文字体设置：skinparam 与 style 两种写法.md","lastUpdated":1794424347000}'),t={name:"工具/PlantUML 中文字体设置：skinparam 与 style 两种写法.md"};function p(i,a,r,o,c,d){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="plantuml-中文字体设置-skinparam-与-style-两种写法" tabindex="-1">PlantUML 中文字体设置：skinparam 与 style 两种写法 <a class="header-anchor" href="#plantuml-中文字体设置-skinparam-与-style-两种写法" aria-label="Permalink to &quot;PlantUML 中文字体设置：skinparam 与 style 两种写法&quot;">​</a></h1> <p>用 PlantUML 画带中文的时序图、类图，渲染出来全是乱码或方块（tofu），是最常遇到的问题之一。原因和解决办法都不复杂：PlantUML 默认字体不含中文字形，需要显式指定一个<strong>渲染环境已安装</strong>的中文字体。这篇文章给出新旧两种写法，以及排查仍然乱码的思路。</p> <h2 id="判定问题" tabindex="-1">判定问题 <a class="header-anchor" href="#判定问题" aria-label="Permalink to &quot;判定问题&quot;">​</a></h2> <p>先明确两点前提：</p> <ol><li>PlantUML 不会自动选择中文字体，未指定时中文按默认字体渲染，缺字形就是方块；</li> <li>指定的字体名必须与系统已安装字体的名称<strong>完全一致</strong>。访问 <a href="https://plantuml.com/font" target="_blank" rel="noreferrer">plantuml.com/font</a> 可以列出当前环境可用的字体名，从里面复制最稳妥。</li></ol> <h2 id="写法一-skinparam-defaultfontname" tabindex="-1">写法一：skinparam defaultFontName <a class="header-anchor" href="#写法一-skinparam-defaultfontname" aria-label="Permalink to &quot;写法一：skinparam defaultFontName&quot;">​</a></h2> <p>经典写法，在图定义开头加一行：</p> <div class="language-plantuml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plantuml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@startuml</span></span>
<span class="line"><span>skinparam defaultFontName Noto Sans CJK SC</span></span>
<span class="line"><span>Client -&gt; Gateway : 提交订单{编号、数量}</span></span>
<span class="line"><span>Gateway -&gt; Service : 创建订单</span></span>
<span class="line"><span></span></span>
<span class="line"><span>note right of Service</span></span>
<span class="line"><span>校验参数合法性</span></span>
<span class="line"><span>写入存储</span></span>
<span class="line"><span>更新订单状态</span></span>
<span class="line"><span>end note</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Service -&gt; Gateway : 成功/失败</span></span>
<span class="line"><span>Gateway -&gt; Client : 成功/失败</span></span>
<span class="line"><span>@enduml</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>常用中文字体名：</p> <table tabindex="0"><thead><tr><th>系统</th> <th>字体名</th></tr></thead> <tbody><tr><td>Linux</td> <td><code>Noto Sans CJK SC</code>（黑体）、<code>Noto Serif CJK SC</code>（宋体）</td></tr> <tr><td>Windows</td> <td><code>Microsoft YaHei</code>、<code>SimSun</code></td></tr></tbody></table> <p>注意 Noto 系列的后缀区分字形区域：<code>SC</code> 简体中文，<code>TC</code> 台湾繁体，<code>HK</code> 香港繁体，按需选择。</p> <h2 id="写法二-style-新版推荐" tabindex="-1">写法二：style（新版推荐） <a class="header-anchor" href="#写法二-style-新版推荐" aria-label="Permalink to &quot;写法二：style（新版推荐）&quot;">​</a></h2> <p><code>skinparam</code> 正被逐步淘汰，新版 PlantUML 推荐用 CSS 风格的 <code>&lt;style&gt;</code> 块：</p> <div class="language-plantuml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plantuml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@startuml</span></span>
<span class="line"><span>&lt;style&gt;</span></span>
<span class="line"><span>document {</span></span>
<span class="line"><span>  FontName Noto Sans CJK SC</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>&lt;/style&gt;</span></span>
<span class="line"><span>@enduml</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>两种写法效果等价，新项目建议直接用 <code>&lt;style&gt;</code>；存量图里的 <code>skinparam</code> 暂时仍可正常工作。</p> <h2 id="还是乱码-环境缺字体" tabindex="-1">还是乱码：环境缺字体 <a class="header-anchor" href="#还是乱码-环境缺字体" aria-label="Permalink to &quot;还是乱码：环境缺字体&quot;">​</a></h2> <p>本机正常、服务器渲染乱码，基本是服务器环境没有中文字体。Linux 服务器安装 Noto CJK 字体包后再渲染：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonts-noto-cjk</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这也是 CI 流水线里生成 PlantUML 图片出现方块的常见原因——基础镜像通常不带中文字体。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>PlantUML 中文乱码三步排查：确认指定了中文字体（<code>skinparam defaultFontName</code> 或 <code>&lt;style&gt;</code> 的 <code>FontName</code>）；字体名与系统安装的完全一致（<a href="https://plantuml.com/font" target="_blank" rel="noreferrer">plantuml.com/font</a> 查询）；渲染环境确实装了该字体（服务器装 <code>fonts-noto-cjk</code>）。</p> <h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2> <ul><li><a href="https://plantuml.com/skinparam" target="_blank" rel="noreferrer">官方文档：skinparam</a></li> <li><a href="https://plantuml.com/font" target="_blank" rel="noreferrer">官方文档：字体</a></li> <li><a href="https://plantuml.com/style-evolution" target="_blank" rel="noreferrer">PlantUML 风格演化：CSS Style</a></li></ul>`,42)])])}const b=n(t,[["render",p]]);export{u as __pageData,b as default};
